package net.officefloor.hq.app.paste;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Add a draft claim per pasted line, in order, for the person on the sheet with that name (ignoring case).
 *  One change: every line is checked first by the claim form's rules, so a refused line adds nothing and
 *  writes no audit record; otherwise each claim is added and written as CLAIM_ADDED. */
public class PasteClaims {
    private record Checked(Person person, PasteLine line, LocalDate date) {
    }

    public void paste(@PathVariable("sheetId") String sheetId, @Val PasteInput input,
            ServerHttpConnection connection, PersonRepository people, ClaimRepository claims, SheetRepository sheets,
            PeriodRepository periods, Audit audit, Rollup rollup, Out<PasteResult> result) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!people.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        LocalDate entry = sheets.entryDate(id);
        List<Checked> checked = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        int n = 0;
        for (PasteLine line : input.lines()) {
            n++;
            try {
                Person person = people.findByName(id, line.name());
                if (person == null) {
                    throw new BadRequestException("no one on the sheet is named " + line.name());
                }
                LocalDate date = line.claim().date() != null ? line.claim().date() : entry;
                PeriodGuard.open(periods, id, claims.dueBy(id, person.id(), date));
                people.claimAllowed(id, person.id(), date);
                line.claim().checkCorrection(claims, id, person.id());
                line.claim().checkRef(claims, id, null);
                if (line.claim().ref() != null && !refs.add(line.claim().ref().toLowerCase(Locale.ROOT))) {
                    throw new BadRequestException("reference " + line.claim().ref() + " is given twice in the paste");
                }
                checked.add(new Checked(person, line, date));
            } catch (BadRequestException e) {
                throw new BadRequestException("line " + n + ": " + e.getMessage());
            }
        }
        for (Checked c : checked) {
            Rollup.Snapshot before = rollup.take(id);
            Claim added = claims.add(id, c.person().id(), c.line().claim().amount(), c.date(), c.line().claim().note(), null, c.line().claim().ref());
            claims.log(id, added.id(), by);
            audit.record("CLAIM_ADDED sheet=" + id + " by=" + by + " person=" + c.person().name()
                    + " amount=" + added.amount() + " date=" + added.date() + Claim.auditRef(added.ref()));
            if (added.lateEntry()) {
                audit.record("LATE_ENTRY sheet=" + id + " by=" + by + " person=" + c.person().name()
                        + " amount=" + added.amount() + " date=" + added.date());
            }
            rollup.record(id, by, before);
        }
        result.set(new PasteResult(checked.size()));
    }
}
package net.officefloor.hq.app.paste;

import java.util.List;

/** A validated paste: its lines, in order. */
public record PasteInput(List<PasteLine> lines) {
}
package net.officefloor.hq.app.paste;

import net.officefloor.hq.app.claim.ClaimInput;

/** One pasted line, bound by the claim form's rules: the person's name (trimmed) and their claim. */
public record PasteLine(String name, ClaimInput claim) {
}
package net.officefloor.hq.app.paste;

/** The paste box: lines of name,amount,date,note. */
public record PasteRequest(String text) {
}
package net.officefloor.hq.app.paste;

/** How many draft claims a paste added. */
public record PasteResult(int added) {
}
package net.officefloor.hq.app.paste;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPaste {
    public void respond(@Val PasteResult result, ObjectResponse<PasteResult> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.paste;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the paste box: each non-blank line is name,amount,date,note — the name is required (trimmed), the
 *  amount and date follow the claim form's rules (a blank date: the sheet's entry date, else its today), and the note is the rest
 *  of the line (it may hold commas, or be absent); a note ending in " #<reference>" gives the claim that external reference. A paste with no lines is refused. */
public class ValidatePaste {
    /** A note ending in " #<reference>": the note before it, and the reference. */
    private static final Pattern REF = Pattern.compile("(.*) #(\\S.*)");

    public void validate(@RequestBody PasteRequest request, Out<PasteInput> paste) throws BadRequestException {
        String text = request == null || request.text() == null ? "" : request.text();
        List<PasteLine> lines = new ArrayList<>();
        int n = 0;
        for (String raw : text.split("\r?\n", -1)) {
            n++;
            if (raw.isBlank()) {
                continue;
            }
            String[] f = raw.split(",", 4);
            String name = f[0].trim();
            String amount = f.length > 1 ? f[1].trim() : "";
            String date = f.length > 2 ? f[2].trim() : "";
            String note = f.length > 3 ? f[3].trim() : "";
            String ref = null;
            Matcher tail = REF.matcher(note);
            if (tail.matches()) {
                note = tail.group(1).trim();
                ref = tail.group(2).trim();
            }
            if (name.isEmpty()) {
                throw new BadRequestException("line " + n + ": name is required");
            }
            LocalDate on = null;
            if (!date.isEmpty()) {
                try {
                    on = LocalDate.parse(date);
                } catch (DateTimeParseException e) {
                    throw new BadRequestException("line " + n + ": date must be yyyy-mm-dd");
                }
            }
            try {
                lines.add(new PasteLine(name, new ClaimInput(ClaimInput.signedAmount(amount), on, note, null, ref, null)));
            } catch (BadRequestException e) {
                throw new BadRequestException("line " + n + ": " + e.getMessage());
            }
        }
        if (lines.isEmpty()) {
            throw new BadRequestException("paste at least one line");
        }
        paste.set(new PasteInput(lines));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.web.bind.annotation.PathVariable;

public class AddPerson {
    public void add(@PathVariable("sheetId") String sheetId, @Val PersonRequest request,
            ServerHttpConnection connection, PersonRepository repository, Audit audit, Rollup rollup, Out<Person> person)
            throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        if (repository.nameTaken(id, request.name(), 0)) {
            throw new BadRequestException("name is already in use");
        }
        String contact = request.contact().isEmpty() ? null : request.contact();
        if (contact != null && repository.contactTaken(id, contact, 0)) {
            throw new BadRequestException("contact is already in use");
        }
        Rollup.Snapshot before = rollup.take(id);
        Person added;
        try {
            added = repository.add(id, request.name(), request.grade(),
                    request.terms().isEmpty() ? null : Integer.valueOf(request.terms()), contact);
        } catch (DuplicateKeyException e) {
            throw new BadRequestException("name is already in use");
        }
        audit.record("PERSON_ADDED sheet=" + id + " by=" + by + " name=" + added.name()
                + " grade=" + added.grade() + (added.terms() == null ? "" : " terms=" + added.terms())
                + (added.contact() == null ? "" : " contact=" + added.contact()));
        rollup.record(id, by, before);
        person.set(added);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the person form: a name is required (trimmed; unique on the sheet, checked when saved), the grade
 *  must be A, B or C, and a from-date is yyyy-mm-dd (blank for the sheet's today), and the terms
 *  a whole number of days from 0 to 3650 (blank for none), and the contact is trimmed and
 *  lower-cased (blank for none; unique on the sheet, checked when saved). */
public class ValidatePerson {
    private static final Set<String> GRADES = Set.of("A", "B", "C");
    private static final Pattern TERMS = Pattern.compile("\\d{1,4}");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> person) throws BadRequestException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (name.isEmpty()) {
            throw new BadRequestException("name is required");
        }
        if (!GRADES.contains(grade)) {
            throw new BadRequestException("grade must be A, B or C");
        }
        String from = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!from.isEmpty()) {
            try {
                from = LocalDate.parse(from).toString();
            } catch (DateTimeParseException e) {
                throw new BadRequestException("from-date must be yyyy-mm-dd");
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && (!TERMS.matcher(terms).matches() || Integer.parseInt(terms) > 3650)) {
            throw new BadRequestException("terms must be a whole number of days from 0 to 3650");
        }
        String contact = request.contact() == null ? "" : request.contact().trim().toLowerCase(java.util.Locale.ROOT);
        person.set(new PersonRequest(name, grade, request.version(), from,
                terms.isEmpty() ? "" : String.valueOf(Integer.parseInt(terms)), contact));
    }
}
package net.officefloor.hq.app.person;

/** The person form; {@code gradeFrom} is the date the grade is in force from (yyyy-mm-dd; blank for the
 *  sheet's today; an edit only), {@code terms} the person's own terms in days (blank for none), {@code contact} their contact (trimmed and lower-cased; blank for none), {@code version} the version the editor loaded (an edit only). */
public record PersonRequest(String name, String grade, Long version, String gradeFrom, String terms, String contact) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<Person> response) {
        response.send(person);
